package com.hospital.system.service; import com.hospital.system.model.Payment; import com.hospital.system.dto.PaymentRequest; import com.hospital.system.repository.*; import com.hospital.system.exception.ApiException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.math.*; @Service public class PaymentService {private final PaymentRepository r; private final BillingRepository b; public PaymentService(PaymentRepository r,BillingRepository b){this.r=r;this.b=b;} public List<Payment> all(Long id){b.one(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Bill not found"));return r.all(id);} @Transactional public Payment add(Long bill,PaymentRequest x){var summary=b.one(bill).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Bill not found"));BigDecimal balance=summary.totalAmount.subtract(r.paid(bill));if(x.amount.compareTo(balance)>0)throw new ApiException(HttpStatus.BAD_REQUEST,"Payment exceeds outstanding balance");if(!Set.of("CASH","CARD","UPI","BANK_TRANSFER").contains(x.paymentMethod))throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid payment method");Payment p=new Payment();p.amount=x.amount;p.paymentMethod=x.paymentMethod;p.referenceNo=x.referenceNo;r.add(bill,p);return r.all(bill).get(0);} }
